package interpreter;

import nodes.ProgramNode;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.logging.*;
import java.util.List;

public class App {
    private static final Logger logger = Logger.getLogger("");

    public String getGreeting() {
        return "Hello World!";
    }

    public static void main(String[] args) {
        String filePath;

        if (args.length == 0) {
            filePath = "src/main/java/lexors/program.lexor"; // default
            //System.out.println("No args provided. Using default: " + filePath);
        } else {
            filePath = args[0];
        }

        String sourceFile = "";

        try {
            System.out.println("Reading: " + filePath);
            sourceFile = readFile(filePath);
        } catch (IOException e) {
            logger.info("File couldn't be opened: " + filePath);
            System.exit(1);
        }

        Lexer lexer = new Lexer(sourceFile);
        List<Token> tokens = lexer.tokenize();
//        System.out.println(tokens);
//        System.out.println();
        // Pass `tokens` to class `Parser` constructor and method should return AST tree. (But I think with no packages to shortcut)
        Parser parser = new Parser(tokens);
        ProgramNode ast = parser.parseProgram();

//        System.out.println("\n=== EXECUTION OUTPUT ===");
//        System.out.println("\n=== ABSTRACT SYNTAX TREE ===");
//        System.out.print(ast);
//        System.out.println("\n=== EXECUTION OUTPUT ===");

        Interpreter interpreter = new Interpreter();

        interpreter.execute(ast);
    }

    private static String readFile(String path) throws IOException {
        return new String(Files.readAllBytes(Paths.get(path)));
    }
}
